package com.company.skillplatform.bundle.infrastructure.entity;
import com.company.skillplatform.common.infrastructure.entity.BaseJpaEntity;import com.company.skillplatform.compatibility.infrastructure.entity.PlatformEntity;import com.company.skillplatform.user.infrastructure.entity.IamUserEntity;import jakarta.persistence.*;
@Entity@Table(name="skill_bundle")public class SkillBundleEntity extends BaseJpaEntity{
 @Column(name="bundle_key",nullable=false,length=64,unique=true)private String bundleKey;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="platform_id")private PlatformEntity platform;@Column(name="os_type",nullable=false,length=32)private String osType;@Column(name="include_dependencies",nullable=false)private boolean includeDependencies;@Column(name="lock_hash",nullable=false,length=64)private String lockHash;@Column(name="resolver_version",nullable=false,length=32)private String resolverVersion;@Column(name="object_key",length=512)private String objectKey;@Column(name="file_name",length=255)private String fileName;@Column(name="size_bytes")private Long sizeBytes;@Column(length=64)private String sha256;@Column(nullable=false,length=32)private String status;@Column(name="retry_count",nullable=false)private int retryCount;@Column(name="error_code",length=64)private String errorCode;@Column(name="error_message",length=1024)private String errorMessage;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="created_by")private IamUserEntity createdBy;@Version@Column(name="version_no",nullable=false)private int versionNo;
 protected SkillBundleEntity(){}public SkillBundleEntity(String key,PlatformEntity p,String os,boolean includeDependencies,String lock,IamUserEntity user){bundleKey=key;platform=p;osType=os;this.includeDependencies=includeDependencies;lockHash=lock;resolverVersion="1";status="BUILDING";createdBy=user;}
 public void available(String object,long size,String hash){objectKey=object;sizeBytes=size;sha256=hash;fileName="bundle-"+bundleKey+".zip";status="AVAILABLE";errorCode=null;errorMessage=null;}public void failed(String code,String message){status="FAILED";errorCode=code;errorMessage=message;retryCount++;}
 public String getBundleKey(){return bundleKey;}public PlatformEntity getPlatform(){return platform;}public String getOsType(){return osType;}public boolean isIncludeDependencies(){return includeDependencies;}public String getObjectKey(){return objectKey;}public String getFileName(){return fileName;}public Long getSizeBytes(){return sizeBytes;}public String getSha256(){return sha256;}public String getStatus(){return status;}public int getRetryCount(){return retryCount;}public String getErrorCode(){return errorCode;}public String getErrorMessage(){return errorMessage;}public IamUserEntity getCreatedBy(){return createdBy;}
}
